/* ui/fx.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../context.js";

export function install(P) {


  function fxPercent(value) {
    return `${Math.round(P.clamp(Number(value) || 0, 0, 1) * 100)}%`;
  }

  function drawFxCanvas(canvas, draw) {
    if (!(canvas instanceof HTMLCanvasElement)) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const w = canvas.width, h = canvas.height;
    const bg = P.cssVar("--bg-elevated-2") || "#141414";
    const border = P.cssVar("--border") || "#2a2a2a";
    const text = P.cssVar("--text") || "#ffffff";
    const muted = P.cssVar("--muted") || "#a3a3a3";
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = border;
    ctx.lineWidth = 1;
    for (let i = 1; i < 4; i++) {
      const x = (w * i) / 4;
      const y = (h * i) / 4;
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke();
    }
    draw(ctx, { w, h, bg, border, text, muted });
  }

  function drawFxVisuals() {
    document.querySelectorAll("#playerDistortionCanvas").forEach((canvas) => {
      P.drawFxCanvas(canvas, (ctx, m) => {
        const pad = 12;
        const innerW = m.w - pad * 2, innerH = m.h - pad * 2;
        ctx.strokeStyle = m.border;
        ctx.beginPath(); ctx.moveTo(pad, pad + innerH / 2); ctx.lineTo(m.w - pad, pad + innerH / 2); ctx.stroke();
        ctx.beginPath();
        for (let i = 0; i <= innerW; i++) {
          const input = (i / innerW) * 2 - 1;
          const output = P.distortionCurveAt(input, P.state.distortionDrive);
          const x = pad + i;
          const y = pad + (innerH * (1 - output)) / 2;
          if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
        }
        ctx.strokeStyle = P.state.distortionEnabled ? m.text : m.muted;
        ctx.lineWidth = 2;
        ctx.stroke();
        ctx.beginPath();
        ctx.arc(pad + P.clamp(P.state.distortionTone, 0, 1) * innerW, pad + innerH / 2, 5, 0, Math.PI * 2);
        ctx.fillStyle = P.state.distortionEnabled ? m.text : m.muted;
        ctx.fill();
      });
    });

    document.querySelectorAll("#playerSaturationCanvas").forEach((canvas) => {
      P.drawFxCanvas(canvas, (ctx, m) => {
        const pad = 12;
        const innerW = m.w - pad * 2, innerH = m.h - pad * 2;
        ctx.strokeStyle = m.border;
        ctx.beginPath(); ctx.moveTo(pad, pad + innerH / 2); ctx.lineTo(m.w - pad, pad + innerH / 2); ctx.stroke();
        ctx.beginPath();
        for (let i = 0; i <= innerW; i++) {
          const input = (i / innerW) * 2 - 1;
          const output = P.saturationCurveAt(input, P.state.saturationDrive);
          const x = pad + i;
          const y = pad + (innerH * (1 - output)) / 2;
          if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
        }
        ctx.strokeStyle = P.state.saturationEnabled ? m.text : m.muted;
        ctx.lineWidth = 2;
        ctx.stroke();
        ctx.beginPath();
        ctx.arc(pad + P.clamp(P.state.saturationTone, 0, 1) * innerW, pad + innerH / 2, 5, 0, Math.PI * 2);
        ctx.fillStyle = P.state.saturationEnabled ? m.text : m.muted;
        ctx.fill();
      });
    });

    const fxWave = (id, range, value, cycles, amplitude, enabled) => {
      document.querySelectorAll(id).forEach((canvas) => {
        P.drawFxCanvas(canvas, (ctx, m) => {
          const pad = 12;
          const innerW = m.w - pad * 2, innerH = m.h - pad * 2;
          const center = pad + innerH / 2;
          const norm = (P.clamp(value, range.min, range.max) - range.min) / (range.max - range.min);
          const amp = innerH * (0.08 + amplitude * 0.4);
          ctx.strokeStyle = m.border;
          ctx.beginPath(); ctx.moveTo(pad, center); ctx.lineTo(m.w - pad, center); ctx.stroke();
          ctx.beginPath();
          for (let i = 0; i <= innerW; i++) {
            const x = pad + i;
            const y = center - Math.sin((i / innerW) * Math.PI * 2 * cycles) * amp;
            if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
          }
          ctx.strokeStyle = enabled ? m.text : m.muted;
          ctx.lineWidth = 2;
          ctx.stroke();
          ctx.beginPath();
          ctx.arc(pad + norm * innerW, center - amp, 5, 0, Math.PI * 2);
          ctx.fillStyle = enabled ? m.text : m.muted;
          ctx.fill();
        });
      });
    };
    fxWave("#playerPhaserCanvas", P.FX_RANGES.phaserRate, P.state.phaserRate,
      1 + P.state.phaserRate / P.FX_RANGES.phaserRate.max * 8, P.state.phaserDepth, P.state.phaserEnabled);
    fxWave("#playerTremoloCanvas", P.FX_RANGES.tremoloRate, P.state.tremoloRate,
      1 + P.state.tremoloRate / P.FX_RANGES.tremoloRate.max * 10, P.state.tremoloDepth, P.state.tremoloEnabled);
    fxWave("#playerVibratoCanvas", P.FX_RANGES.vibratoRate, P.state.vibratoRate,
      1 + P.state.vibratoRate / P.FX_RANGES.vibratoRate.max * 8, P.state.vibratoDepth, P.state.vibratoEnabled);
    fxWave("#playerRingmodCanvas", P.FX_RANGES.ringmodFreq, P.state.ringmodFreq,
      2 + P.state.ringmodFreq / P.FX_RANGES.ringmodFreq.max * 38, P.state.ringmodDepth, P.state.ringmodEnabled);

    document.querySelectorAll("#playerChorusCanvas").forEach((canvas) => {
      P.drawFxCanvas(canvas, (ctx, m) => {
        const pad = 12;
        const innerW = m.w - pad * 2, innerH = m.h - pad * 2;
        const center = pad + innerH / 2;
        const cycles = 1 + (P.clamp(P.state.chorusRate, P.FX_RANGES.chorusRate.min, P.FX_RANGES.chorusRate.max) / P.FX_RANGES.chorusRate.max) * 5;
        const amplitude = innerH * (0.12 + P.clamp(P.state.chorusDepth, 0, 1) * 0.34);
        ctx.strokeStyle = m.border;
        ctx.beginPath(); ctx.moveTo(pad, center); ctx.lineTo(m.w - pad, center); ctx.stroke();
        ctx.beginPath();
        for (let i = 0; i <= innerW; i++) {
          const x = pad + i;
          const y = center - Math.sin((i / innerW) * Math.PI * 2 * cycles) * amplitude;
          if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
        }
        ctx.strokeStyle = P.state.chorusEnabled ? m.text : m.muted;
        ctx.lineWidth = 2;
        ctx.stroke();
        const handleX = pad + ((P.state.chorusRate - P.FX_RANGES.chorusRate.min) / (P.FX_RANGES.chorusRate.max - P.FX_RANGES.chorusRate.min)) * innerW;
        const handleY = center - amplitude;
        ctx.beginPath(); ctx.arc(handleX, handleY, 5, 0, Math.PI * 2);
        ctx.fillStyle = P.state.chorusEnabled ? m.text : m.muted;
        ctx.fill();
      });
    });

    document.querySelectorAll("#playerFlangerCanvas").forEach((canvas) => {
      P.drawFxCanvas(canvas, (ctx, m) => {
        const pad = 12;
        const innerW = m.w - pad * 2, innerH = m.h - pad * 2;
        const center = pad + innerH / 2;
        const rate = P.clamp(P.state.flangerRate, P.FX_RANGES.flangerRate.min, P.FX_RANGES.flangerRate.max);
        const depth = P.clamp(P.state.flangerDepth, P.FX_RANGES.flangerDepth.min, P.FX_RANGES.flangerDepth.max);
        const cycles = 1 + (rate / P.FX_RANGES.flangerRate.max) * 8;
        const amplitude = innerH * (0.1 + depth * 0.38);
        ctx.strokeStyle = m.border;
        ctx.beginPath(); ctx.moveTo(pad, center); ctx.lineTo(m.w - pad, center); ctx.stroke();
        ctx.beginPath();
        for (let i = 0; i <= innerW; i++) {
          const x = pad + i;
          const y = center - Math.sin((i / innerW) * Math.PI * 2 * cycles) * amplitude;
          if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
        }
        ctx.strokeStyle = P.state.flangerEnabled ? m.text : m.muted;
        ctx.lineWidth = 2;
        ctx.stroke();
        const handleX = pad + ((rate - P.FX_RANGES.flangerRate.min) / (P.FX_RANGES.flangerRate.max - P.FX_RANGES.flangerRate.min)) * innerW;
        const handleY = center - amplitude;
        ctx.beginPath(); ctx.arc(handleX, handleY, 5, 0, Math.PI * 2);
        ctx.fillStyle = P.state.flangerEnabled ? m.text : m.muted;
        ctx.fill();
      });
    });

    document.querySelectorAll("#playerDelayCanvas").forEach((canvas) => {
      P.drawFxCanvas(canvas, (ctx, m) => {
        const pad = 12;
        const innerW = m.w - pad * 2, innerH = m.h - pad * 2;
        const time = P.clamp(P.state.delayTime, P.FX_RANGES.delayTime.min, P.FX_RANGES.delayTime.max);
        const feedback = P.clamp(P.state.delayFeedback, P.FX_RANGES.delayFeedback.min, P.FX_RANGES.delayFeedback.max);
        const spacing = (time / P.FX_RANGES.delayTime.max) * (innerW / 6);
        ctx.strokeStyle = m.border;
        ctx.beginPath(); ctx.moveTo(pad, pad + innerH); ctx.lineTo(m.w - pad, pad + innerH); ctx.stroke();
        for (let i = 0; i < 7; i++) {
          const level = Math.pow(feedback / P.FX_RANGES.delayFeedback.max, i);
          const x = pad + i * spacing;
          const height = innerH * (0.18 + level * 0.72);
          ctx.strokeStyle = P.state.delayEnabled ? m.text : m.muted;
          ctx.globalAlpha = 0.25 + level * 0.75;
          ctx.lineWidth = 2;
          ctx.beginPath(); ctx.moveTo(x, pad + innerH); ctx.lineTo(x, pad + innerH - height); ctx.stroke();
        }
        ctx.globalAlpha = 1;
      });
    });

    document.querySelectorAll("#playerReverbCanvas").forEach((canvas) => {
      P.drawFxCanvas(canvas, (ctx, m) => {
        const pad = 12;
        const innerW = m.w - pad * 2, innerH = m.h - pad * 2;
        const center = pad + innerH / 2;
        const decayNorm = (P.clamp(P.state.reverbDecay, P.FX_RANGES.reverbDecay.min, P.FX_RANGES.reverbDecay.max) - P.FX_RANGES.reverbDecay.min) / (P.FX_RANGES.reverbDecay.max - P.FX_RANGES.reverbDecay.min);
        const stretch = 0.25 + decayNorm * 0.75;
        const top = [], bottom = [];
        for (let i = 0; i <= innerW; i++) {
          const t = i / innerW;
          const envelope = Math.exp((-5 * t) / stretch) * innerH * 0.45;
          top.push({ x: pad + i, y: center - envelope });
          bottom.push({ x: pad + i, y: center + envelope });
        }
        ctx.beginPath();
        top.forEach((p, i) => { if (i === 0) ctx.moveTo(p.x, p.y); else ctx.lineTo(p.x, p.y); });
        for (let i = bottom.length - 1; i >= 0; i--) ctx.lineTo(bottom[i].x, bottom[i].y);
        ctx.closePath();
        ctx.fillStyle = P.state.reverbEnabled ? "rgba(255,255,255,0.12)" : "rgba(163,163,163,0.08)";
        ctx.fill();
        ctx.beginPath();
        top.forEach((p, i) => { if (i === 0) ctx.moveTo(p.x, p.y); else ctx.lineTo(p.x, p.y); });
        ctx.strokeStyle = P.state.reverbEnabled ? m.text : m.muted;
        ctx.lineWidth = 2;
        ctx.stroke();
        const handleX = pad + decayNorm * innerW;
        const handleY = pad + innerH * (1 - P.clamp(P.state.reverbMix, 0, 1));
        ctx.beginPath(); ctx.arc(handleX, handleY, 5, 0, Math.PI * 2);
        ctx.fillStyle = P.state.reverbEnabled ? m.text : m.muted;
        ctx.fill();
      });
    });
  }
  function fxCanvasPoint(canvas, ev) {
    const rect = canvas.getBoundingClientRect();
    return {
      x: P.clamp((ev.clientX - rect.left) / rect.width, 0, 1),
      y: P.clamp((ev.clientY - rect.top) / rect.height, 0, 1),
    };
  }
  function applyFxCanvasDrag(canvas, ev) {
    if (!P.fxDrag.kind) return;
    const p = P.fxCanvasPoint(canvas, ev);
    const round = (v) => Math.round(v * 100) / 100;
    if (P.fxDrag.kind === "distortion") {
      P.state.distortionTone = round(p.x);
      P.state.distortionDrive = round(1 - p.y);
    } else if (P.fxDrag.kind === "saturation") {
      P.state.saturationTone = round(p.x);
      P.state.saturationDrive = round(1 - p.y);
    } else if (P.fxDrag.kind === "phaser") {
      P.state.phaserRate = round(P.FX_RANGES.phaserRate.min + p.x * (P.FX_RANGES.phaserRate.max - P.FX_RANGES.phaserRate.min));
      P.state.phaserDepth = round(1 - p.y);
    } else if (P.fxDrag.kind === "tremolo") {
      P.state.tremoloRate = round(P.FX_RANGES.tremoloRate.min + p.x * (P.FX_RANGES.tremoloRate.max - P.FX_RANGES.tremoloRate.min));
      P.state.tremoloDepth = round(1 - p.y);
    } else if (P.fxDrag.kind === "vibrato") {
      P.state.vibratoRate = round(P.FX_RANGES.vibratoRate.min + p.x * (P.FX_RANGES.vibratoRate.max - P.FX_RANGES.vibratoRate.min));
      P.state.vibratoDepth = round(1 - p.y);
    } else if (P.fxDrag.kind === "ringmod") {
      P.state.ringmodFreq = Math.round(P.FX_RANGES.ringmodFreq.min + p.x * (P.FX_RANGES.ringmodFreq.max - P.FX_RANGES.ringmodFreq.min));
      P.state.ringmodDepth = round(1 - p.y);
    } else if (P.fxDrag.kind === "chorus") {
      P.state.chorusRate = round(P.FX_RANGES.chorusRate.min + p.x * (P.FX_RANGES.chorusRate.max - P.FX_RANGES.chorusRate.min));
      P.state.chorusDepth = round(1 - p.y);
    } else if (P.fxDrag.kind === "flanger") {
      P.state.flangerRate = round(P.FX_RANGES.flangerRate.min + p.x * (P.FX_RANGES.flangerRate.max - P.FX_RANGES.flangerRate.min));
      P.state.flangerDepth = round(1 - p.y);
    } else if (P.fxDrag.kind === "delay") {
      P.state.delayTime = round(P.FX_RANGES.delayTime.min + p.x * (P.FX_RANGES.delayTime.max - P.FX_RANGES.delayTime.min));
      P.state.delayFeedback = round(p.y * P.FX_RANGES.delayFeedback.max);
    } else if (P.fxDrag.kind === "reverb") {
      P.state.reverbDecay = round(P.FX_RANGES.reverbDecay.min + p.x * (P.FX_RANGES.reverbDecay.max - P.FX_RANGES.reverbDecay.min));
      P.state.reverbMix = round(1 - p.y);
    }
    P.applyFxState();
    P.syncSettingsUI();
    P.saveState();
    P.notify("settings");
  }
  function bindFxCanvasInteractions() {
    document.querySelectorAll(".fx-visual").forEach((canvas) => {
      if (!(canvas instanceof HTMLCanvasElement) || canvas.dataset.fxBound === "1") return;
      canvas.dataset.fxBound = "1";
      canvas.style.touchAction = "none";
      const kind = String(canvas.id || "").replace(/^player/, "").replace(/Canvas$/, "").toLowerCase();
      canvas.addEventListener("pointerdown", (ev) => {
        if (!P.FX_KINDS.includes(kind)) return;
        P.state[`${kind}Enabled`] = true;
        P.fxDrag.kind = kind;
        P.fxDrag.pointerId = ev.pointerId;
        try { canvas.setPointerCapture?.(ev.pointerId); } catch {}
        P.applyFxCanvasDrag(canvas, ev);
      });
      canvas.addEventListener("pointermove", (ev) => {
        if (P.fxDrag.pointerId !== ev.pointerId || P.fxDrag.kind !== kind) return;
        P.applyFxCanvasDrag(canvas, ev);
      });
      const end = (ev) => {
        if (P.fxDrag.pointerId !== ev.pointerId) return;
        P.fxDrag.kind = null;
        P.fxDrag.pointerId = null;
        P.drawFxVisuals();
      };
      canvas.addEventListener("pointerup", end);
      canvas.addEventListener("pointercancel", end);
    });
  }

  function syncFxVisual() {
    P.bindFxCanvasInteractions();
    P.drawFxVisuals();
    document.querySelectorAll("#playerDistortionSummary").forEach((el) => {
      el.textContent = `${P.fxPercent(P.state.distortionDrive)} / ${P.fxPercent(P.state.distortionTone)}`;
    });
    document.querySelectorAll("#playerSaturationSummary").forEach((el) => {
      el.textContent = `${P.fxPercent(P.state.saturationDrive)} / ${P.fxPercent(P.state.saturationTone)}`;
    });
    document.querySelectorAll("#playerPhaserSummary").forEach((el) => {
      el.textContent = `${Number(P.state.phaserRate).toFixed(2)} Hz / ${P.fxPercent(P.state.phaserDepth)}`;
    });
    document.querySelectorAll("#playerTremoloSummary").forEach((el) => {
      el.textContent = `${Number(P.state.tremoloRate).toFixed(1)} Hz / ${P.fxPercent(P.state.tremoloDepth)}`;
    });
    document.querySelectorAll("#playerVibratoSummary").forEach((el) => {
      el.textContent = `${Number(P.state.vibratoRate).toFixed(1)} Hz / ${P.fxPercent(P.state.vibratoDepth)}`;
    });
    document.querySelectorAll("#playerRingmodSummary").forEach((el) => {
      el.textContent = `${Math.round(P.state.ringmodFreq)} Hz / ${P.fxPercent(P.state.ringmodDepth)}`;
    });
    document.querySelectorAll("#playerChorusSummary").forEach((el) => {
      el.textContent = `${P.state.chorusRate.toFixed(1)} Hz / ${P.fxPercent(P.state.chorusDepth)}`;
    });
    document.querySelectorAll("#playerFlangerSummary").forEach((el) => {
      el.textContent = `${Number(P.state.flangerRate).toFixed(2)} Hz / ${P.fxPercent(P.state.flangerDepth)}`;
    });
    document.querySelectorAll("#playerDelaySummary").forEach((el) => {
      el.textContent = `${Math.round(Number(P.state.delayTime) * 1000)} ${P.pt("ms")} / ${P.fxPercent(P.state.delayFeedback)}`;
    });
    document.querySelectorAll("#playerReverbSummary").forEach((el) => {
      el.textContent = `${Number(P.state.reverbDecay).toFixed(1)} s / ${P.fxPercent(P.state.reverbMix)}`;
    });
    document.querySelectorAll("[data-fx-setting]").forEach((root) => {
      const kind = root.dataset.fxSetting;
      if (!P.FX_KINDS.includes(kind)) return;
      const enabled = !!P.state[`${kind}Enabled`];
      root.classList.toggle("is-disabled", !enabled);
      root.querySelectorAll("input,select,button").forEach((el) => {
        if (el.dataset.playerSetting === `${kind}Enabled` || el.closest(".eq-toggle")) return;
        el.disabled = !enabled;
      });
    });
  }
  Object.assign(P, { fxPercent, drawFxCanvas, drawFxVisuals, fxCanvasPoint, applyFxCanvasDrag, bindFxCanvasInteractions, syncFxVisual });
}
